func boolPtr(b bool) *bool { return &b }
func strPtr(s string) *string { return &s }

func TestConstructConsistentHash(t *testing.T) {
	dur := kgateway.ConsistentHashDuration("1h30m")
	secs := kgateway.ConsistentHashDuration("3600")

	tests := []struct {
		name      string
		spec      kgateway.TrafficPolicySpec
		expectNil bool
		check     func(t *testing.T, ir *consistentHashIR)
		expectErr bool
	}{
		{
			name:      "nil produces nil",
			spec:      kgateway.TrafficPolicySpec{},
			expectNil: true,
		},
		{
			name: "empty produces empty",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				assert.NotNil(t, ir)
				assert.Len(t, ir.headers, 0)
				assert.Nil(t, ir.sourceIp)
			},
		},
		{
			name: "disable",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{Disable: boolPtr(true)},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				require.NotNil(t, ir)
				require.NotNil(t, ir.disable)
				assert.True(t, *ir.disable)
			},
		},
		{
			name: "headers dedupe case-insensitive",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Headers: []kgateway.ConsistentHashHeader{
						{HeaderName: "X-User-Id", Terminal: boolPtr(true)},
						{HeaderName: "x-user-id"},
						{HeaderName: "X-Session-Id"},
					},
				},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				require.Len(t, ir.headers, 2)
				assert.Equal(t, "X-User-Id", ir.headers[0].headerName)
				assert.True(t, ir.headers[0].terminal)
				assert.Equal(t, "X-Session-Id", ir.headers[1].headerName)
			},
		},
		{
			name: "cookies with ttl formats and attributes",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Cookies: []kgateway.ConsistentHashCookie{
						{
							Name: "session",
							TTL:  &dur,
							Path: strPtr("/api"),
							Attributes: []kgateway.ConsistentHashCookieAttribute{
								{Name: "SameSite", Value: strPtr("Strict")},
								{Name: "Secure", Value: strPtr("true")},
							},
							Terminal: boolPtr(true),
						},
						{Name: "other", TTL: &secs},
						{Name: "session"}, // duplicate by name
					},
				},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				require.Len(t, ir.cookies, 2)
				c := ir.cookies[0]
				assert.Equal(t, "session", c.name)
				assert.Equal(t, 90*time.Minute, c.ttl)
				assert.True(t, c.ttlSet)
				assert.Equal(t, "/api", c.path)
				assert.True(t, c.terminal)
				require.Len(t, c.attributes, 2)
				assert.Equal(t, "SameSite", c.attributes[0].Name)
				assert.Equal(t, "Strict", c.attributes[0].Value)
				assert.Equal(t, "Secure", c.attributes[1].Name)
				assert.Equal(t, "true", c.attributes[1].Value)
				assert.Equal(t, "other", ir.cookies[1].name)
				assert.Equal(t, time.Hour, ir.cookies[1].ttl)
			},
		},
		{
			name: "invalid ttl",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Cookies: []kgateway.ConsistentHashCookie{
						{Name: "session", TTL: ptrTo(kgateway.ConsistentHashDuration("bogus"))},
					},
				},
			},
			expectErr: true,
		},
		{
			name: "query and filter state",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					QueryParameters: []kgateway.ConsistentHashQueryParameter{
						{Name: "q", Terminal: boolPtr(true)},
						{Name: "q"},
					},
					FilterState: []kgateway.ConsistentHashFilterState{
						{Key: "key1"},
						{Key: "key1", Terminal: boolPtr(true)},
					},
				},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				require.Len(t, ir.queryParameters, 1)
				assert.Equal(t, "q", ir.queryParameters[0].name)
				assert.True(t, ir.queryParameters[0].terminal)
				require.Len(t, ir.filterState, 1)
				assert.Equal(t, "key1", ir.filterState[0].key)
				assert.False(t, ir.filterState[0].terminal)
			},
		},
		{
			name: "sourceIp",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: boolPtr(true)},
				},
			},
			check: func(t *testing.T, ir *consistentHashIR) {
				require.NotNil(t, ir.sourceIp)
				assert.True(t, ir.sourceIp.terminal)
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out := &trafficPolicySpecIr{}
			err := constructConsistentHash(tt.spec, out)
			if tt.expectErr {
				assert.Error(t, err)
				return
			}
			require.NoError(t, err)
			if tt.expectNil {
				assert.Nil(t, out.consistentHash)
				return
			}
			require.NotNil(t, out.consistentHash)
			if tt.check != nil {
				tt.check(t, out.consistentHash)
			}
		})
	}
}

func ptrTo[T any](v T) *T { return &v }

func TestApplyConsistentHash(t *testing.T) {
	tests := []struct {
		name           string
		ir             *consistentHashIR
		expectNil      bool
		expectPolicies []*envoyroutev3.RouteAction_HashPolicy
	}{
		{
			name:      "nil does nothing",
			ir:        nil,
			expectNil: true,
		},
		{
			name:      "disable clears",
			ir:        &consistentHashIR{disable: boolPtr(true)},
			expectNil: true,
		},
		{
			name: "empty defaults to sourceIp",
			ir:   &consistentHashIR{},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				sourceIPHashPolicy(false),
			},
		},
		{
			name: "canonical order and all types",
			ir: &consistentHashIR{
				headers: []consistentHashHeaderIR{{headerName: "h", terminal: true}},
				cookies: []consistentHashCookieIR{{name: "c"}},
				queryParameters: []consistentHashQueryParameterIR{{name: "q"}},
				filterState: []consistentHashFilterStateIR{{key: "f"}},
				sourceIp: &consistentHashSourceIPIR{terminal: true},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{Terminal: true, PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{Header: &envoyroutev3.RouteAction_HashPolicy_Header{HeaderName: "h"}}},
				{Terminal: false, PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{Name: "c"}}},
				{Terminal: false, PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: "q"}}},
				{Terminal: false, PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: "f"}}},
				{Terminal: true, PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{SourceIp: true}}},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			action := &envoyroutev3.RouteAction{}
			if tt.ir != nil {
				action.HashPolicy = []*envoyroutev3.RouteAction_HashPolicy{{}}
			}
			applyConsistentHash(tt.ir, action)
			if tt.expectNil {
				assert.Nil(t, action.HashPolicy)
				return
			}
			require.Len(t, action.HashPolicy, len(tt.expectPolicies))
			for i := range tt.expectPolicies {
				assert.True(t, proto.Equal(tt.expectPolicies[i], action.HashPolicy[i]), "policy %d differs: %v vs %v", i, tt.expectPolicies[i], action.HashPolicy[i])
			}
		})
	}
}

func TestMergeConsistentHash(t *testing.T) {
	mergeOpts := func() (ir.MergeOrigins) { return ir.MergeOrigins{} }

	policyWith := func(ch *kgateway.ConsistentHash) *TrafficPolicy {
		spec := kgateway.TrafficPolicySpec{ConsistentHash: ch}
		out := &trafficPolicySpecIr{}
		err := constructConsistentHash(spec, out)
		if err != nil {
			panic(err)
		}
		return &TrafficPolicy{spec: *out}
	}

	t.Run("adopts lower wholesale when higher has none", func(t *testing.T) {
		p1 := &TrafficPolicy{}
		p2 := policyWith(&kgateway.ConsistentHash{Headers: []kgateway.ConsistentHashHeader{{HeaderName: "h"}}, SourceIP: &kgateway.ConsistentHashSourceIP{}})
		origins := mergeOpts()
		mergeConsistentHash(p1, p2, &ir.AttachedPolicyRef{Name: "p2"}, nil, policy.MergeOptions{}, origins, TrafficPolicyMergeOpts{})
		require.NotNil(t, p1.spec.consistentHash)
		require.Len(t, p1.spec.consistentHash.headers, 1)
		require.NotNil(t, p1.spec.consistentHash.sourceIp)
		assert.Equal(t, []string{"p2"}, origins.Get("consistentHash"))
	})

	t.Run("unions arrays and keeps higher sourceIp unset", func(t *testing.T) {
		p1 := policyWith(&kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{HeaderName: "X-A"}},
		})
		p2 := policyWith(&kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{
				{HeaderName: "X-B"},
				{HeaderName: "x-a"}, // duplicate case-insensitive
			},
			SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: boolPtr(true)},
		})
		origins := mergeOpts()
		mergeConsistentHash(p1, p2, &ir.AttachedPolicyRef{Name: "p2"}, nil, policy.MergeOptions{}, origins, TrafficPolicyMergeOpts{})
		require.Len(t, p1.spec.consistentHash.headers, 2)
		assert.Equal(t, "X-A", p1.spec.consistentHash.headers[0].headerName)
		assert.Equal(t, "X-B", p1.spec.consistentHash.headers[1].headerName)
		assert.Nil(t, p1.spec.consistentHash.sourceIp, "higher-priority unset sourceIp must win")
		assert.Equal(t, []string{"p2"}, origins.Get("consistentHash"))
	})

	t.Run("higher sourceIp wins", func(t *testing.T) {
		p1 := policyWith(&kgateway.ConsistentHash{SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: boolPtr(true)}})
		p2 := policyWith(&kgateway.ConsistentHash{SourceIP: &kgateway.ConsistentHashSourceIP{}})
		origins := mergeOpts()
		mergeConsistentHash(p1, p2, &ir.AttachedPolicyRef{Name: "p2"}, nil, policy.MergeOptions{}, origins, TrafficPolicyMergeOpts{})
		require.NotNil(t, p1.spec.consistentHash.sourceIp)
		assert.True(t, p1.spec.consistentHash.sourceIp.terminal)
		assert.Nil(t, origins.Get("consistentHash"))
	})

	t.Run("higher disable wins when set", func(t *testing.T) {
		p1 := policyWith(&kgateway.ConsistentHash{Disable: boolPtr(false), Headers: []kgateway.ConsistentHashHeader{{HeaderName: "h"}}})
		p2 := policyWith(&kgateway.ConsistentHash{Disable: boolPtr(true)})
		origins := mergeOpts()
		mergeConsistentHash(p1, p2, &ir.AttachedPolicyRef{Name: "p2"}, nil, policy.MergeOptions{}, origins, TrafficPolicyMergeOpts{})
		require.NotNil(t, p1.spec.consistentHash.disable)
		assert.False(t, *p1.spec.consistentHash.disable)
		assert.Nil(t, origins.Get("consistentHash"))
	})

	t.Run("lower disable applies when higher unset", func(t *testing.T) {
		p1 := policyWith(&kgateway.ConsistentHash{Headers: []kgateway.ConsistentHashHeader{{HeaderName: "h"}}})
		p2 := policyWith(&kgateway.ConsistentHash{Disable: boolPtr(true)})
		origins := mergeOpts()
		mergeConsistentHash(p1, p2, &ir.AttachedPolicyRef{Name: "p2"}, nil, policy.MergeOptions{}, origins, TrafficPolicyMergeOpts{})
		require.NotNil(t, p1.spec.consistentHash.disable)
		assert.True(t, *p1.spec.consistentHash.disable)
		assert.Equal(t, []string{"p2"}, origins.Get("consistentHash"))
	})
}
